import json
from pathlib import Path

import pytest

from baloo.standards.glob import UnsupportedGlobError, match

# Generated by running github.com/bmatcuk/doublestar/v4 v4.10.0 Match, the matcher the Bluebear
# handler uses for skill enforcement rules, over every pattern x path pair.
FIXTURE = Path(__file__).parent / "fixtures" / "doublestar_cases.json"


def test_matches_doublestar_on_every_fixture_case():
    data = json.loads(FIXTURE.read_text())
    expected = {tuple(pair) for pair in data["matches"]}
    mismatches = [
        (pattern, path)
        for i, pattern in enumerate(data["patterns"])
        for j, path in enumerate(data["paths"])
        if match(pattern, path) != ((i, j) in expected)
    ]
    assert mismatches == []


@pytest.mark.parametrize("pattern", ["*.{go,py}", "[ab]/x", "a\\*b"])
def test_rejects_syntax_it_cannot_match_like_doublestar(pattern):
    with pytest.raises(UnsupportedGlobError):
        match(pattern, "a/x")
